const expressionText=async locator=>(await locator.textContent()).replace(/\u200b/g,'').replaceAll('−','-').replaceAll('×','*').replaceAll('÷','/');
import {test,expect,open,edit} from './fixtures.mjs';
async function moveCalculator(page){const header=page.getByRole('dialog',{name:'Scratch calculator'}).locator('header'),b=await header.boundingBox();await page.mouse.move(b.x+70,b.y+20);await page.mouse.down();await page.mouse.move(390,20,{steps:4});await page.mouse.up();}

