 await expect(panel.getByText('Saved values',{exact:true})).toBeVisible();await expect(panel.locator('.calculator-snapshots')).toBeHidden();await panel.getByRole('button',{name:'Source for 100',exact:true}).click();await expect(panel.locator('.calculator-source')).toContainText('sum of 4 cells');await panel.getByRole('button',{name:'Close source',exact:true}).click();
 await panel.screenshot({path:`/tmp/mds-calculator-${test.info().project.name}.png`});
 const work=await (await page.request.get(studio.url+'/saved_queries.json')).json();expect(work.calculator.history.at(-1).result).toBe(25);
