for(const temporal of [true,false])test(`calculator picks ${temporal?'time':'category'} line observations and selected-line totals`,async({page,studio})=>{
 await page.setViewportSize({width:1440,height:1100});await open(page,studio.url);
 await edit(page,`SELECT ${temporal?"DATE '2025-01-01' + i::INTEGER":"'Day ' || (i+1)"} AS day, s AS series, 10+i*10+CASE WHEN s='B' THEN 30 ELSE 0 END AS amount FROM range(3)t(i) CROSS JOIN (VALUES ('A'),('B'))u(s) ORDER BY day,series`);
 await page.locator('#runBtn').click();await expect(page.locator('#results')).toContainText('amount');await page.locator('#viewSeg [data-v=chart]').click();const bar=page.locator('#chartbar');await bar.getByRole('button',{name:/Chart settings/}).click();await bar.getByRole('combobox',{name:'Chart',exact:true}).selectOption('line');await bar.getByRole('combobox',{name:'Series',exact:true}).selectOption('series');await bar.getByRole('combobox',{name:'Legend style',exact:true}).selectOption('list');await bar.getByRole('button',{name:/Chart settings/}).click();
 const chart=page.locator('#chart'),lines=chart.locator('.mark-line.role-mark path');await expect(lines).toHaveCount(2);
 const point=()=>lines.first().evaluate(el=>{const p=el.getPointAtLength(el.getTotalLength()/2),m=el.getScreenCTM();return {x:p.x*m.a+p.y*m.c+m.e,y:p.x*m.b+p.y*m.d+m.f};});
 await page.getByRole('button',{name:'Calculator',exact:true}).click();await moveCalculator(page);const panel=page.getByRole('dialog',{name:'Scratch calculator'});let p=await point();await page.mouse.move(p.x,p.y);await expect(page.locator('.calculator-chart-preview:visible')).toContainText('Add 20 to calculator');await expect(chart.locator('.calculator-chart')).toHaveCSS('cursor','pointer');await page.mouse.click(p.x,p.y);await expect(page.locator('.calculator-chart-preview:visible')).toHaveCount(0);await expect(panel.locator('.calculator-answer')).toHaveText('= 20');await expect(chart.locator('.line-series-tools')).toContainText('Hover a series · click to select');
 await panel.getByRole('button',{name:'Clear expression',exact:true}).click();await chart.getByRole('button',{name:'Select all',exact:true}).click();p=await point();await page.mouse.move(p.x,p.y);await expect(page.locator('.calculator-chart-preview:visible')).toContainText('Add 70 to calculator');await expect(page.locator('.calculator-chart-preview:visible')).toContainText('2 selected series');await page.locator('#saveBtn').hover();await expect(page.locator('.calculator-chart-preview:visible')).toHaveCount(0);await page.mouse.click(p.x,p.y);await expect(panel.locator('.calculator-answer')).toHaveText('= 70');await expect(chart.locator('.line-series-tools')).toContainText('2 pinned');await expect(panel.locator('.calculator-status')).toHaveText('Saved to project');
 if(temporal){await panel.getByRole('button',{name:'Clear expression',exact:true}).click();const box=await chart.locator('.studioPanSurface path').boundingBox();await page.keyboard.down('Shift');await page.mouse.move(box.x+1,box.y+1);await page.mouse.down();await page.mouse.move(box.x+box.width-1,box.y+box.height-1,{steps:5});await page.mouse.up();await page.keyboard.up('Shift');await expect(page.getByRole('group',{name:'Selected chart values'})).toContainText('2 selected');await expect(panel.locator('.calculator-answer')).toHaveText('= 70');await panel.getByRole('button',{name:'Clear expression',exact:true}).click();await chart.getByRole('button',{name:'Zoom in',exact:true}).click();await expect(chart.locator('.calculator-chart')).toHaveCSS('cursor','grab');await page.keyboard.down('Shift');await expect(chart.locator('.calculator-chart')).toHaveCSS('cursor','crosshair');await page.keyboard.down('ControlOrMeta');await expect(chart.locator('.calculator-chart')).toHaveCSS('cursor',/url\(.*10 10, crosshair/);await page.keyboard.up('ControlOrMeta');await expect(chart.locator('.calculator-chart')).toHaveCSS('cursor','crosshair');await page.keyboard.up('Shift');await expect(chart.locator('.calculator-chart')).toHaveCSS('cursor','grab');const bounds=await chart.locator('.studioPanSurface path').boundingBox();const x=bounds.x+bounds.width/2,y=bounds.y+bounds.height/2;await page.mouse.move(x,y);await page.mouse.down();await page.mouse.move(x+60,y,{steps:6});await page.mouse.up();await expect(panel.getByLabel('Calculation',{exact:true})).toBeEmpty();await page.mouse.click(x,y);await expect(panel.locator('.calculator-answer')).toHaveText('= 70');await expect(panel.locator('.calculator-status')).toHaveText('Saved to project');}
});
test('calculator adds values, changes operators and wraps highlighted expressions without typing',async({page,studio})=>{
 await page.setViewportSize({width:1440,height:1100});await open(page,studio.url);await edit(page,"SELECT * FROM (VALUES (10),(20),(5)) t(amount)");await page.locator('#runBtn').click();await expect(page.locator('#results')).toContainText('amount');await page.getByRole('button',{name:'Calculator',exact:true}).click();await moveCalculator(page);
 const panel=page.getByRole('dialog',{name:'Scratch calculator'}),editor=panel.getByLabel('Calculation',{exact:true}),answer=panel.locator('.calculator-answer'),cells=page.locator('#results tbody td:not(.rn)');
 await cells.nth(0).click();await cells.nth(1).click();await expect(answer).toHaveText('= 30');await editor.getByRole('button',{name:'Change operator +',exact:true}).click();await page.getByRole('menuitem',{name:'− Subtract',exact:true}).click();await expect(answer).toHaveText('= -10');await panel.getByRole('button',{name:'Multiply',exact:true}).click();await cells.nth(2).click();await expect(answer).toHaveText('= -90');
 await editor.focus();await page.keyboard.press('ControlOrMeta+A');await panel.getByRole('button',{name:'Wrap selection in parentheses'}).click();await expect.poll(()=>expressionText(editor)).toBe('(10 - 20*5)');await expect(answer).toHaveText('= -90');
 // Wrapping leaves the caret after the group, ready for the next operation.
 await panel.getByRole('button',{name:'Divide',exact:true}).click();await cells.nth(2).click();await expect(answer).toHaveText('= -18');await expect(panel.locator('.calculator-status')).toHaveText('Saved to project');
 await panel.getByRole('button',{name:'Clear expression',exact:true}).click();await page.keyboard.insertText('10 + 20 * 5');await editor.evaluate(el=>{const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){if(node.textContent.includes('20')){const range=document.createRange();range.setStart(el,0);range.setEnd(node,node.textContent.indexOf('20')+2);const selection=getSelection();selection.removeAllRanges();selection.addRange(range);break;}}});await panel.getByRole('button',{name:'Wrap selection in parentheses'}).click();await expect.poll(()=>expressionText(editor)).toBe('(10 + 20) * 5');await expect(answer).toHaveText('= 150');await expect(panel.locator('.calculator-status')).toHaveText('Saved to project');await panel.getByRole('button',{name:'Close calculator'}).click();await page.reload();await expect(page.locator('#status')).toContainText('Ready');await page.getByRole('button',{name:'Calculator',exact:true}).click();await moveCalculator(page);await editor.getByRole('button',{name:'Change operator +',exact:true}).click();await page.getByRole('menuitem',{name:'− Subtract',exact:true}).click();await expect(answer).toHaveText('= -50');await expect(panel.locator('.calculator-status')).toHaveText('Saved to project');await panel.screenshot({path:`/tmp/mds-calculator-operators-${test.info().project.name}.png`});
});
