test('clicking a whitespace gap between numbers offers an operator',async({page,studio})=>{
 await open(page,studio.url);await page.getByRole('button',{name:'Calculator',exact:true}).click();await moveCalculator(page);const panel=page.getByRole('dialog',{name:'Scratch calculator'}),editor=panel.getByLabel('Calculation',{exact:true});
 const clickSpace=async()=>{const p=await editor.evaluate(el=>{const walker=document.createTreeWalker(el,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const match=/ +/.exec(node.textContent);if(match){const r=document.createRange();r.setStart(node,match.index);r.setEnd(node,match.index+match[0].length);const b=r.getBoundingClientRect();return {x:b.x+b.width/2,y:b.y+b.height/2};}}});await page.mouse.click(p.x,p.y);};
 for(const spaces of [' ','   ']){await panel.getByRole('button',{name:'Clear expression',exact:true}).click();await page.keyboard.insertText('87'+spaces+'9');await clickSpace();const menu=page.getByRole('menu',{name:'Insert operator'});await expect(menu).toBeVisible();await menu.getByRole('menuitem',{name:'× Multiply',exact:true}).click();await expect(panel.locator('.calculator-answer')).toHaveText('= 783');await expect.poll(()=>expressionText(editor)).toBe('87 * 9');}
 await panel.getByRole('button',{name:'Clear expression',exact:true}).click();await page.keyboard.insertText('87 + 9');await clickSpace();await expect(page.getByRole('menu',{name:'Insert operator'})).toHaveCount(0);await expect(panel.locator('.calculator-answer')).toHaveText('= 96');await expect(panel.locator('.calculator-status')).toHaveText('Saved to project');
});
