test('dropdown only changes statistic while readout and calculator result copy exact numbers',async({page,studio})=>{
 await open(page,studio.url);await page.evaluate(()=>{window.copiedStatistics=[];Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async text=>window.copiedStatistics.push(text)}});});
 await edit(page,'SELECT 12345.6789 AS amount');await page.locator('#runBtn').click();const cell=page.locator('#results tbody td:not(.rn)').first();await expect(cell).toContainText('12345');await cell.click();const readout=page.getByRole('button',{name:'Selection statistic',exact:true});await page.getByRole('button',{name:'Change selection statistic',exact:true}).click();await page.locator('.calculator-stat-menu [data-stat=sum]').click();expect(await page.evaluate(()=>window.copiedStatistics)).toEqual([]);const arrow=page.getByRole('button',{name:'Change selection statistic',exact:true}),beforeReadout=await readout.boundingBox(),beforeArrow=await arrow.boundingBox();await readout.click();await expect(readout).toHaveAttribute('data-copy-status','Copied');expect(await readout.boundingBox()).toEqual(beforeReadout);expect(await arrow.boundingBox()).toEqual(beforeArrow);await page.locator('#resultFooter').screenshot({path:`/tmp/mds-copy-feedback-${test.info().project.name}.png`});await expect.poll(()=>page.evaluate(()=>window.copiedStatistics)).toEqual(['12345.6789']);await expect(page.getByRole('menu',{name:'Choose selection statistic'})).toBeHidden();await expect(page.locator('#results td.sel')).toHaveCount(1);await expect(page.getByRole('dialog',{name:'Scratch calculator'})).toBeHidden();
 await page.getByRole('button',{name:'Change selection statistic',exact:true}).click();await page.locator('.calculator-stat-menu [data-stat=nonNullCount]').click();await expect(readout).toHaveText('Count 1');expect(await page.evaluate(()=>window.copiedStatistics)).toEqual(['12345.6789']);await readout.click();await expect.poll(()=>page.evaluate(()=>window.copiedStatistics)).toEqual(['12345.6789','1']);
 await page.getByRole('button',{name:'Open calculator',exact:true}).click();const panel=page.getByRole('dialog',{name:'Scratch calculator'});await panel.getByLabel('Calculation',{exact:true}).click();await page.keyboard.insertText('10 / 3');const answer=panel.locator('.calculator-answer');await expect(answer).toContainText('3.333');await answer.click();await expect.poll(()=>page.evaluate(()=>window.copiedStatistics.at(-1))).toBe(String(10/3));await answer.focus();await page.keyboard.press('Enter');await expect.poll(()=>page.evaluate(()=>window.copiedStatistics.length)).toBe(4);
});
